# Function to find the shortest path between two craters using BFS
def shortest_path(graph, start, end):
    queue = collections.deque([(start,)])  # queue of (node, path)
    visited = set([start])
    while queue:
        node = queue.popleft()
        if len(node) >= 1000:  # Early stop to prevent stack overflow for long paths
            return [-1, -1]
        if node[0] == end:
            return [-1, len(node) - 1]  # Length of path plus start index
        for neighbor in graph.get(node[0], []):
            if neighbor not in visited:
                returned = shortest_path(graph, neighbor, end)
                if -1 in returned:
                    return returned
                if returned[1] * len(node) < len(node) * returned[1]:
                    return returned
                else:
                    queue.append(node + [(neighbor,) + returned[2]])
                visited.add(neighbor)
    return [-1, -1]  # Either haven't found the end yet or visited every path


