import collections

def max_simple_paths(n, edges):
    if n == 2:
        return 0  # No need to add an edge if there are only two vertices
    if n == 3:
        return 1  # Adding an edge between any two of the three vertices will create two paths

    # Initialize distance and last values in reverse tree
    distance = collections.defaultdict(int)
    last_nodes = collections.defaultdict(int)

    # Build the trees
    trees = {}
    for u, v in edges:
        trees.setdefault(u, collections.defaultdict(int))
        trees.setdefault(v, collections.defaultdict(int))
        for vertex in (u, v):
            trees[vertex][u] = max(distance.get(v, 0), distance.get(u, 0)) + 1
            trees[vertex][v] = max(distance.get(u, 0), distance.get(v, 0)) + 1
        distance[u] = 1
        distance[v] = 1

    # Label each node in all trees by the smallest integer k storing path length of n-k+1 and k+1
    label = 0
    labels = set()
    inorder_reversed_trees = {}
    for vertex in reversed(trees):
        tmp_labels = {v: prefix for v, prefix in sorted(trees[vertex].items()) if v not in labels}
        for new_label in tmp_labels:
            labels.add(new_label)
            if new_label not in inorder_reversed_trees:
                inorder_reversed_trees[new_label] = collections.deque()
            inorder_reversed_trees[new_label].append(new_label)
        for new_label in tmp_labels:
            inorder_reversed_trees[new_label].appendleft(new_label)

    path_lengths = {}
    for vertex in trees:
        stacked = []
        res = 0
        for _ in range(len(inorder_reversed_trees), 2 * n + 1):
            if vertex not in labels:
                if vertex not in stacked:
                    for k, p in tmp_labels.items():
                        path_lengths.setdefault(k, [0, 0])
                        path_lengths[k] = [
                            max(path_lengths[k][0], current) + distances
                            for current, distances in stacked
                        ]
                elif len(inorder_reversed_trees[vertex]) <= n:
                    current, distances = stacked.pop()
                    path_lengths[vertex] = current + distances
                vertex = inorder_reversed_trees[vertex].popleft()
        path_lengths[vertex] = path_lengths[vertex][1]  # Only use the second count
        res += 1

    return sum(k * square_count // 2 for k, square_count in path_lengths.items())


