import sys

class SegmentTree:
    def __init__(self, size):
        self.size = 1 << (size - 1).bit_length()
        self.tree = [0] * (2 * self.size)

    def update(self, index, value):
        index += self.size
        self.tree[index] = value
        while index > 1:
            index >>= 1
            self.tree[index] = (self.tree[index * 2] + self.tree[index * 2 + 1]) % 95542721

    def get_sum(self, left, right):
        left += self.size
        right += self.size
        s = 0
        while left <= right:
            if left & 1:
                s += self.tree[left]
                left += 1
            if not right & 1:
                s += self.tree[right]
                right -= 1
            left >>= 1
            right >>= 1
        return s % 95542721

