import sys

def dijkstra(graph, start):
    from collections import deque
    import heapq

    distances = {}
    distances[None] = float('inf')
    distances[start] = 0
    distance_queue = [(0, start)]
    visited = set()

    while distance_queue:
        current_distance, current_node = heapq.heappop(distance_queue)

        if current_node in visited:
            continue
        visited.add(current_node)

        for next_node, weight in graph[current_node]:
            if next_node not in visited and (current_distance + weight) < distances[next_node]:
                distances[next_node] = current_distance + weight
                heapq.heappush(distance_queue, (current_distance + weight, next_node))

    return distances

def solve():
    input()
    n = int(input())
    graph = [[] for _ in range(n)]
    edges = [list(map(int, input().split())) for _ in range(n - 1)]

    for u, v in edges:
        graph[u - 1].append((v - 1, 1))
        graph[v - 1].append((u - 1, 1))

    min_distance = float('inf')
    for u in range(n):
        for v in range(n):
            if graph[u] and graph[v]:
                min_distance = min(min_distance, dijkstra(graph, u)[v])

    result = ["{} {}".format(u, v) for u, v in edges] + [f"{u} {v} {min_distance}" for u in range(n) for v in range(n) if u < v]
    return "\n".join(result)

if __name__ == "__main__":
    print(solve())
