import sys

def find(parent, node):
    if parent[node] == node:
        return node
    parent[node] = find(parent, parent[node])
    return parent[node]

def union(parent, rank, node1, node2):
    root1 = find(parent, node1)
    root2 = find(parent, node2)
    if root1 == root2:
        return
    if rank[root1] < rank[root2]:
        parent[root1] = root2
    elif rank[root1] > rank[root2]:
        parent[root2] = root1
    else:
        parent[root2] = root1
        rank[root1] += 1

def kruskal_mst(parent, rank, edges, edges_used, E_max, M_max, N):
    mst_used = 0
    for i in range(N - 1):
        e, a, b = edges[i]
        if find(parent, a) != find(parent, b):
            union(parent, rank, a, b)
            E_max.append(e)
            mst_used += 1
            if mst_used == M_max:
                break
    return E_max

