import sys

def bron_kerbosch(G, P, X, R, stack=[]):
    if len(P) + len(R) == 1 and not X:
        yield stack + R
    else:
        for x in sorted(P, key=lambda x: len(G[x])):
            yield from bron_kerbosch(G, P-{x}, X&P[x], x, stack+[x])

def get_triangle_edges(tree):
