    def diameter(G, r, cycle_set):
        stack = [r]
        depths = [0]*len(G)
        while stack:
            v = stack.pop()
            if depths[v] < depths[stack[0]]:
                stack[0] = v
            for u in G[v]:
                if (u != v and depths[u] == depths[v]) or u in cycle_set:
                    stack.append(u)
                    depths[u] = depths[v] + 1
                    continue
                if depths[u] < depths[v]:
                    cycle_set.add(v)
                    cycle_set.add(u)
                    stack[:] = stack + [v, u]
                    depth = depths[u]
                    if x > depth:
                        x = depth
                    stack = [u, v] + stack
                    while stack and stack[-1] in cycle_set:
                        stack.pop()
                    cycle_set -= {stack.pop(), u}
                elif depth < x:
