                        stack[:] = stack[:1] + [v, u]
                        cycle_set[p1] |= set([v, u])
                        cycle_set[t2] &= set([v, u])
                    stack.append(u)
                    depths[u] = depths[v] + 1
                    stack.append(v)
        return stack

    # Flatten the graph
