                r1.append(n)
        G[1-m] = {i: G[(n,m)[i]] for i in range(m) for n in G1}
        G1 = {(n,m)[i] for i in range(m) for n in G1}

    # Use the Kruskal's algorithm to partition the graph into a forest of triangles
    cycle_set, X, R = set([1]), set(), set()
    cycle_set.add(1)
    for edge in sorted(diameter(G1, 1, cycle_set), key=lambda x: G1.wr(x[0])[-1]):
