import heapq

def build_max_graph(n, edges):
    graph = [[] for _ in range(n)]
    for a, b, w in edges:
        graph[a-1].append((b-1, w))
        graph[b-1].append((a-1, w))
    return graph

def dijkstra(graph, start):
    distances = [float('inf')] * len(graph)
    distances[start] = 0
    priority_queue = [(0, start)]
    while priority_queue:
        current_distance, current_vertex = heapq.heappop(priority_queue)
        if current_distance > distances[current_vertex]:
            continue
        for neighbor, weight in graph[current_vertex]:
            distance = current_distance + weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(priority_queue, (distance, neighbor))
    return distances

def find_max_energy(graph, times_per_corridor):
    max_energy = 0
    for _, energy in times_per_corridor:
        max_energy = max(max_energy, energy)
    return max_energy * 2 - 1

def solve(n, m, edges, times_per_corridor):
    graph = build_max_graph(n, edges)
    max_energy = find_max_energy(graph, times_per_corridor)
    max_energy_modified = [0] * m
    for i, (_, energy) in enumerate(times_per_corridor):
        if energy > max_energy:
            graph = build_max_graph(n, edges)
            max_energy = find_max_energy(graph, times_per_corridor)
        distance = dijkstra(graph, (i,))
        corners = [v for v, d in distance.items() if d >= 2]
        if len(corners) > 0:
            max_energy_modified[i] = max_energy
        else:
            max_energy_modified[i] = 2 * max_energy_modified[i]
    for i in range(m):
        print(max_energy_modified[i])

