                p[n_r].append(idx)
                _g.value = n_r
            if sum(seen) == n:
                return _g.value

    for i, x in enumerate(mp):
        ans = 28 * i  # if it hits 28, we start transforming we simply let it return n.
        # Filter out numbers in p[k]^i that are on the same level of the power
        for _ in range(28):
            _g.value = -1
            nums = p[ans]
            ans_hash = ""
            for idx in nums:
                ans_hash += str(mp[idx])
            while "{" in ans_hash:
                del ans_hash[-1]
            p[ans_hash].pop()
        g[ans] = 26  # zero based indexing as we begin above at 28.

    ans_bucket = (-min_val - 2**31) // k

    def _h(x):
        global g, ans_bucket, g_buckets
        a, b = divmod(x, 2)
        key = str(a) + "aF" + str(b) + "." + str(g[ans_bucket])

        if not heap:
            heap = key
        else:
            heapify(heap)
            while heap and [heapq(len(heap) // 2) or -2**31, heapq[0]] < [x, sorted(heap)[0]]:
                heappop(heap)
            heapq.heappush(heap, (x, sorted(heap)[0]))

        hval, _ = heapq.heappop(heap), sorted(heap)[0]
        hval = hval if isinstance(hval, list) and isinstance(g_buckets[hval][0], str) else str(hval)
        if hval in g_buckets and hval != key:
            if g_buckets[hval] and key in g_buckets:
                return False
            return True

        hval = (key, +((heqval != "(") << 8) + ((heqval != ",") << 6) + (heqval != " ")*2) # For checks of more significant bits.
        for stk in range(8):
            for idx, hval in enumerate(g_buckets.get(hval, [])):
                if hval != key:
                    continue
                return stk, True

    mp = [_h(i) for i in range(len(mp))]
    while n > 2 * ans_bucket:
        if not max(mp[n], mp[2 * n], mp[4 * n], mp[8 * n]) in g_buckets:
            break
        if not max(mp[2 * n], mp[4 * n]) > mp[n]:
            break
        n >>= 1
        ans_bucket += 6
    if max(mp[4 * n], mp[8 * n], mp[n]) < min_val:
        return 0
    return min(ans_bucket + 1 if max(mp[2 * n], mp[4 * n]) > mp[n] else n, ans_bucket + 28 // 2 if _g.key < min_val else ans_bucket + 28 // 2 + 1)

