s = input().strip()
n = len(s)

# Initialize distance table for each pair of characters
dist = [[0 for _ in range(n)] for _ in range(n)]
ltr = {}

# Fill the distance table: distance[i][j] is the number of operations to move from i to j
for i in range(n):
    for j in range(n):
        if s[i] == s[j]:
            dist[i][j] = i if i == j else i - j
            ltr[(i, j)] = s[i]
        else:
            dist[i][j] = max(i, n - i - j)
            if dist[i][j] > 1:
                dist[i][j] = n * 2 - 1

# Compute the final answer using dynamic programming
dp = [[0 for _ in range(n)] for _ in range(n)]
visited = set()

# Fill the DP table: dp[i][j] is the minimum distance to reach j if the cursor is initially at i
for i in range(n):
    for j in range(n):
        if (i, j) in ltr or (i, j) in visited:
            continue
        visited.add((i, j))
        for k in range(n):
            if (i, k) in ltr and k != j:
                if (k, j) in ltr:
                    dp[i][j] = max(dp[i][j], dp[k][j])
                else:
                    dp[i][j] = max(dp[i][j], dp[k][j] + dist[k][j] * 2 + dist[k][i])
        visited.remove((i, j))

# Sum up all the distances in the DP table
