from math import gcd
from fractions import Fraction

def lcm(x, y):
    return (x * y) // gcd(x, y)

def solution(n, p):
    area = Fraction(0, 1)
    for i in range(n):
        x1, y1 = p[i]
        x2, y2 = p[(i + 1) % n]
        area += Fraction(x1 * y2 - y1 * x2, 2)

    b = gcd(area.numerator, area.denominator)
    if area.is_integer():
        area = area / b
    else:
        area = Fraction(1, area.denominator) * area

    ways = 0
    for m in range(1, 100):
        now = 1 << m
        l = lcm(now, area.denominator)
        total = now * l - area * l
        ways += total.bit_count()

    return min(ways, (10 ** 9) + 7)

