from collections import defaultdict

def maximize_grade(n, k, ai, edges):
    m = len(ai)
    adj = defaultdict(list)
    for u, v in edges:
        adj[u-1].append(v-1)
        adj[v-1].append(u-1)

    min_ima_at_k_nodes = [float('inf')] * n
    min_parent_ima_at_k_nodes = [-1] * n
    nodes_at_k_distance = {}

    def dfs(current_node, previous_node, k, current_distance):
        nonlocal min_ima_at_k_nodes, min_parent_ima_at_k_nodes, nodes_at_k_distance
        if k == current_distance:
            min_parent_ima_at_k_nodes[current_node] = previous_node
            if current_distance < len(ai):
                min_ima_at_k_nodes[current_node] = ai[current_distance]
            return
        if k < current_distance:
            return
        for next_node in adj[current_node]:
            if next_node != previous_node:
                new_parent = next_node
                new_k_distance = current_distance
                if next_node in nodes_at_k_distance:
                    new_k_distance += nodes_at_k_distance[next_node]
                    if new_k_distance < k:
                        dfs(next_node, previous_node, k, current_distance)
                        return

    for node in range(n):
        dfs(node, -1, k, 0)

    largest_at_k_distance = max(min_ima_at_k_nodes)
    largest_subtree_size = 0
    nodes_in_a_subtree = 0
    def get_maxima(node):
        nonlocal largest_at_k_distance, largest_subtree_size, nodes_in_a_subtree
        ma, sb = defaultdict(lambda: 0), 1
        for child in adj[node]:
            if child == min_parent_ima_at_k_nodes[node]:
                sb -= 1
                continue
            ma[child] += get_maxima(child)
            if sb < ma[min_parent_ima_at_k_nodes[node]]:
                biggest_im_index = child
        if largest_at_k_distance < ma[node]:
            largest_at_k_distance = ma[node]
            nodes_in_a_subtree = sb
        for child in adj[node]:
            if child != min_parent_ima_at_k_nodes[node]:
                ma[node] = max(ma[node], ma[child])
        return max(ma[node], ma[data_entry_idx][node] - (sb - ma[child]) for child, data_entry_idx in nodes_at_k_distance.items())

    return largest_at_k_distance - nodes_in_a_subtree

