from sys import stdin

def build_segment_tree(arr):
    n = len(arr)
    tree = [0] * (4 * n)
    for i in range(n):
        tree[i + n - 1] = arr[i]
    for i in range(n - 2, -1, -1):
        tree[i] = (tree[i * 2 + 1] + tree[i * 2 + 2]) % 95542721
    return tree

def update_tree(tree, start, end, idx, value, tree_size):
    if start == end:
        tree[idx] = value
        return value
    mid = (start + end) // 2
    if idx > mid:
        return update_tree(tree, mid + 1, end, idx, value, tree_size) + (tree[2 * idx + 1] if idx % 2 == 1 else 0) % 95542721
    else:
        return update_tree(tree, start, mid, idx, value, tree_size) + (tree[2 * idx] if idx % 2 == 0 else 0) % 95542721

def query_tree(tree, start, end, l, r, tree_size):
    if r < start or end < l:
        return 0
    elif l <= start and end <= r:
        return tree[(start + end) // 2]
    else:
        mid = (start + end) // 2
        return (query_tree(tree, start, mid, l, r, tree_size) + query_tree(tree, mid + 1, end, l, r, tree_size)) % 95542721

