import sys

def dijkstra(n, graph, start):
    dist = [float('inf')] * n
    dist[start] = 0
    visited = [False] * n
    pq = [(0, start)]
    while pq:
        (cost, node) = pq.pop(0)
        if visited[node]:
            continue
        visited[node] = True
        for neighbour, weight in enumerate(graph[node]):
            if weight < dist[neighbour] or dist[neighbour] == float('inf'):
                dist[neighbour] = weight
                pq.append((cost + weight, neighbour))
    return dist

def find_max_energy(max_dist):
    for e in range(1, 1000001):
        if e > max_dist:
            break
        if max_dist - e == e - max_dist:
            return e
    return -1

n, m = map(int, input().split())
