import math

def find_buttons(u, v, p):
    if math.gcd(p, 2) == 1:
        return 1 if u == v else 0
    elif p == 3:
        return 1 if u == v else 0
    elif u == 0:
        return 0
    elif u == v:
        return 0
    elif v == 1:
        return 1
    elif v == p - 1:
        return 1
    elif u**p-1 != 1:
        return 2
    elif (u + 1) % p != v:
        return 2
    elif u == 1 or v == p - 1:
        return 3
    elif math.lcm(p-2, p-1) == p - 1:
        return 2
    else:
        return 3

def main():
    u, v, p = map(int, input().split())
    l, presses = str(find_buttons(u, v, p)), []
    for i in range(len(l)):
