            presses.insert(0, 2)
        elif l[i] == '1':
            presses.insert(0, 1)
        elif l[i] == '3':
            presses.insert(0, 3)
    print(len(presses))
    print(' '.join(map(str, presses)))

if __name__ == "__main__":
    main()
